import { useCallback } from "react";
import { useEditorRef, useEditorSelector } from "platejs/react";

/**
 * Subscribe to a mark's active state and get a toggle function.
 *
 * Must be used inside a `<RichText>` (or `<Plate>`) context.
 *
 * @param key - The mark plugin key (e.g., `BoldPlugin.key`)
 * @param editorId - Optional editor ID when multiple editors exist under a `PlateController`
 * @returns `{ active, toggle }` — whether the mark is currently applied, and a function to toggle it
 *
 * @example
 * const bold = useMarkState(BoldPlugin.key);
 * <IconButton selected={bold.active} onClick={bold.toggle}>B</IconButton>
 */
export function useMarkState(key: string, editorId?: string) {
  const editor = useEditorRef();
  const active = useEditorSelector(
    (ed) => {
      const marks = ed?.api?.marks?.() || ed?.marks;
      return !!marks?.[key];
    },
    [],
    ...(editorId ? [{ id: editorId }] : []),
  );
  const toggle = useCallback(() => {
    editor.tf.toggleMark(key);
    editor.tf.focus();
  }, [editor, key]);

  return { active, toggle };
}
